SELECT dv, SUM(v) FROM (SELECT (SELECT r.name FROM customer_addresses a JOIN cities c ON c.city_id = a.city_id JOIN regions r ON r.region_id = c.region_id WHERE a.address_id = o.address_id) AS dv, CASE WHEN o.currency = 'BDT' THEN o.total_bdt ELSE o.total_amount * x.bdt_per_unit END AS v FROM orders o LEFT JOIN currency_rates x ON x.rate_date = CAST(o.order_at AS DATE) AND x.currency = o.currency WHERE o.is_deleted = FALSE AND o.status IN ('delivered', 'in_transit', 'returned') AND o.order_at >= TIMESTAMP '2024-10-01 00:00:00' AND o.order_at < TIMESTAMP '2025-01-01 00:00:00') t GROUP BY dv
